version.content:
pipeline {
    agent any

    environment {
        // 远程服务器配置
        REMOTE_HOST = '20.48.1.68'
        REMOTE_USER = 'root'
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id'
        REMOTE_ADDRESS = '/data/soft/e-certificate/'


        // 构建时间戳（用于归档或版本标记）
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))

        // 部署文件名
        DEPLOY_NAME = 'dist'
        // 打包文件名
        ARCHIVE_NAME = '${DEPLOY_NAME}.tar.gz'
    }

    stages {
        stage('Git Checkout') {
            steps {
                echo "Checking out branch: ${params.Branch}"
                checkout scmGit(
                    branches: [[name: "${params.Branch}"]],
                    extensions: [],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: "${GIALAB_ADDRESS}/front/csp/electronic-certificate-h5.git"
                    ]]
                )
            }
        }

        stage('Dependencies Install') {
            steps {
                sh 'node -v'
                sh 'pnpm -v'
                sh 'pnpm install --frozen-lockfile -registry=https://registry.npmmirror.com' // 推荐生产环境使用 --frozen-lockfile
            }
        }

        stage('Build') {
            steps {
                sh 'pnpm run build:h5'
            }
        }

        stage('Deploy to Remote') {
            steps {
                script {

                    echo "Deploying to ${REMOTE_USER}@${REMOTE_HOST}:${REMOTE_ADDRESS}"

                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            pwd
                            # 创建压缩包
                            tar -zcf ${ARCHIVE_NAME} ${DEPLOY_NAME}/

                            # 上传到服务器
                            scp ${ARCHIVE_NAME} ${REMOTE_USER}@${REMOTE_HOST}:${REMOTE_ADDRESS}

                            # 在远程服务器执行命令
                            ssh ${REMOTE_USER}@${REMOTE_HOST} "
                                cd ${REMOTE_ADDRESS}
                                # 删除旧文件
                                # rm -rf ${DEPLOY_NAME}/

                                # 解压新包并清理
                                tar -zxvf ${ARCHIVE_NAME} && rm -f ${ARCHIVE_NAME}

                                # 添加时间戳验证
                                echo \"Deployment successful at \$(date +'%Y-%m-%d %H:%M:%S')\"
                            "
                        """
                    }
                }
            }
        }
    }
}
